package com.credflow.auth.management;
import com.credflow.auth.entity.AuthUser;import com.credflow.auth.repository.AuthUserRepository;
import java.util.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.web.server.ResponseStatusException;
import static org.springframework.http.HttpStatus.*;
@Service @Transactional
public class MarketplaceManagement {
 private final JdbcTemplate jdbc;private final AuthUserRepository users;private final PasswordEncoder encoder;
 public MarketplaceManagement(JdbcTemplate jdbc,AuthUserRepository users,PasswordEncoder encoder){this.jdbc=jdbc;this.users=users;this.encoder=encoder;}
 static void admin(Jwt jwt){if(jwt==null||jwt.getClaimAsStringList("roles")==null||!jwt.getClaimAsStringList("roles").contains("ADMIN")||jwt.getClaimAsString("client_id")!=null)throw new ResponseStatusException(FORBIDDEN,"Administrator access required.");}
 private static final String FIELDS="SELECT O.ORGANIZATION_ID AS \"marketplaceId\",O.ORGANIZATION_NAME AS \"name\",O.ORGANIZATION_STATUS AS \"status\",O.ROW_VERSION AS \"version\",R.REFERENCE_PREFIX AS \"referencePrefix\",(SELECT MIN(U.USERNAME) FROM CF_AUTH_USERS U WHERE U.MARKETPLACE_ID=O.ORGANIZATION_ID AND U.USER_ROLE='MARKETPLACE' AND NOT EXISTS(SELECT 1 FROM CF_AUTH_SERVICE_CLIENTS C WHERE C.USER_ID=U.USER_ID)) AS \"username\",(SELECT MIN(U.EMAIL_ADDRESS) FROM CF_AUTH_USERS U WHERE U.MARKETPLACE_ID=O.ORGANIZATION_ID AND U.USER_ROLE='MARKETPLACE' AND NOT EXISTS(SELECT 1 FROM CF_AUTH_SERVICE_CLIENTS C WHERE C.USER_ID=U.USER_ID)) AS \"emailAddress\",(SELECT COUNT(*) FROM CF_SELLER_PROFILES P WHERE P.MARKETPLACE_ID=O.ORGANIZATION_ID) AS \"sellerCount\" FROM CF_ORGANIZATIONS O LEFT JOIN CF_MARKETPLACE_REFERENCES R ON R.MARKETPLACE_ID=O.ORGANIZATION_ID WHERE O.ORGANIZATION_TYPE='MARKETPLACE'";
 @Transactional(readOnly=true) public Object list(Jwt jwt,int page,int size){admin(jwt);if(page<0||size<1||size>100)throw new IllegalArgumentException("Invalid pagination.");return Map.of("items",jdbc.queryForList(FIELDS+" ORDER BY O.ORGANIZATION_NAME,O.ORGANIZATION_ID OFFSET ? ROWS FETCH NEXT ? ROWS ONLY",(long)page*size,size),"totalElements",jdbc.queryForObject("SELECT COUNT(*) FROM CF_ORGANIZATIONS WHERE ORGANIZATION_TYPE='MARKETPLACE'",Long.class));}
 private Map<String,Object> read(String id){var rows=jdbc.queryForList(FIELDS+" AND O.ORGANIZATION_ID=?",id);if(rows.isEmpty())throw new ResponseStatusException(NOT_FOUND,"Marketplace not found.");return rows.getFirst();}
 public Object read(String id,Jwt jwt){admin(jwt);return read(id);}
 public Object create(MarketplaceInput input,String key,Jwt jwt){
  admin(jwt);try{UUID.fromString(key);}catch(Exception ex){throw new IllegalArgumentException("A valid retry key is required.");}
  if(input.password().getBytes(StandardCharsets.UTF_8).length>72)throw new IllegalArgumentException("Password must contain at most 72 UTF-8 bytes.");
  String name=input.name().trim(),prefix=input.referencePrefix().trim().toUpperCase(Locale.ROOT),username=input.username().trim().toLowerCase(Locale.ROOT),email=input.emailAddress().trim().toLowerCase(Locale.ROOT);if(name.isBlank())throw new IllegalArgumentException("Enter the marketplace name.");
  String retry=jwt.getSubject()+":"+key,hash=hash(List.of(name,prefix,username,email));var prior=jdbc.queryForList("SELECT ORGANIZATION_ID,CREATE_HASH FROM CF_ORGANIZATIONS WHERE CREATE_KEY=?",retry);
  if(!prior.isEmpty()){if(!hash.equals(prior.getFirst().get("CREATE_HASH"))||!users.findByUsernameIgnoreCase(username).map(u->encoder.matches(input.password(),u.getPasswordHash())).orElse(false))throw new ResponseStatusException(CONFLICT,"This retry key was used for different marketplace details.");return read(prior.getFirst().get("ORGANIZATION_ID").toString());}
  if(users.existsByUsernameIgnoreCase(username)||users.existsByEmailAddressIgnoreCase(email))throw new ResponseStatusException(CONFLICT,"Username or email is already registered.");
  if(jdbc.queryForObject("SELECT COUNT(*) FROM CF_MARKETPLACE_REFERENCES WHERE REFERENCE_PREFIX=?",Integer.class,prefix)>0)throw new ResponseStatusException(CONFLICT,"Choose a unique seller reference prefix.");
  String id=UUID.randomUUID().toString();jdbc.update("INSERT INTO CF_ORGANIZATIONS(ORGANIZATION_ID,ORGANIZATION_NAME,ORGANIZATION_TYPE,CREATE_KEY,CREATE_HASH) VALUES (?,?,'MARKETPLACE',?,?)",id,name,retry,hash);jdbc.update("INSERT INTO CF_MARKETPLACE_REFERENCES(MARKETPLACE_ID,REFERENCE_PREFIX,NEXT_NUMBER) VALUES (?,?,1001)",id,prefix);
  var operator=user(username,email,input.password(),id);users.saveAndFlush(operator);
  var machine=user("service.marketplace."+id,"submission."+id+"@service.credflow.invalid",UUID.randomUUID().toString()+UUID.randomUUID(),id);users.saveAndFlush(machine);jdbc.update("INSERT INTO CF_AUTH_SERVICE_CLIENTS(USER_ID,CLIENT_ID,SCOPES) VALUES (?,?,'application.submit')",machine.getUserId(),"marketplace-submission-"+id);
  return read(id);
 }
 private AuthUser user(String username,String email,String password,String market){var user=new AuthUser();user.setUsername(username);user.setEmailAddress(email);user.setPasswordHash(encoder.encode(password));user.setUserRole("MARKETPLACE");user.setMarketplaceId(market);user.setAccountStatus("ACTIVE");return user;}
 private void lock(String id,long version){var rows=jdbc.queryForList("SELECT ROW_VERSION FROM CF_ORGANIZATIONS WHERE ORGANIZATION_ID=? AND ORGANIZATION_TYPE='MARKETPLACE' FOR UPDATE",id);if(rows.isEmpty())throw new ResponseStatusException(NOT_FOUND,"Marketplace not found.");if(((Number)rows.getFirst().get("ROW_VERSION")).longValue()!=version)throw new ResponseStatusException(CONFLICT,"Marketplace changed. Refresh before saving.");}
 public Object update(String id,MarketplaceUpdate input,Jwt jwt){admin(jwt);lock(id,input.expectedVersion());String name=input.name().trim(),email=input.emailAddress().trim().toLowerCase(Locale.ROOT);if(name.isBlank())throw new IllegalArgumentException("Enter the marketplace name.");var operators=jdbc.queryForList("SELECT USER_ID FROM CF_AUTH_USERS U WHERE MARKETPLACE_ID=? AND USER_ROLE='MARKETPLACE' AND NOT EXISTS(SELECT 1 FROM CF_AUTH_SERVICE_CLIENTS C WHERE C.USER_ID=U.USER_ID)",Long.class,id);if(operators.size()!=1)throw new ResponseStatusException(CONFLICT,"This marketplace has multiple operators. Contact the administrator to update its accounts individually.");long operator=operators.getFirst();if(jdbc.queryForObject("SELECT COUNT(*) FROM CF_AUTH_USERS WHERE LOWER(EMAIL_ADDRESS)=? AND USER_ID<>?",Integer.class,email,operator)>0)throw new ResponseStatusException(CONFLICT,"Email is already registered.");jdbc.update("UPDATE CF_AUTH_USERS SET EMAIL_ADDRESS=?,UPDATED_AT=SYSTIMESTAMP,PROFILE_VERSION=PROFILE_VERSION+1 WHERE USER_ID=?",email,operator);jdbc.update("UPDATE CF_ORGANIZATIONS SET ORGANIZATION_NAME=?,ORGANIZATION_STATUS=?,ROW_VERSION=ROW_VERSION+1 WHERE ORGANIZATION_ID=?",name,input.status(),id);return read(id);}
 public Object delete(String id,long version,Jwt jwt){admin(jwt);lock(id,version);
  if(jdbc.queryForObject("SELECT COUNT(*) FROM CF_SELLER_PROFILES WHERE MARKETPLACE_ID=?",Long.class,id)>0||jdbc.queryForObject("SELECT COUNT(*) FROM CF_MARKETPLACE_LOAN_REQUESTS WHERE MARKETPLACE_ID=?",Long.class,id)>0||jdbc.queryForObject("SELECT COUNT(*) FROM CF_AUTH_USERS WHERE MARKETPLACE_ID=? AND USER_ROLE<>'MARKETPLACE'",Long.class,id)>0)throw new ResponseStatusException(CONFLICT,"This marketplace has linked records. Deactivate it instead; records must be preserved.");
  jdbc.update("DELETE FROM CF_AUTH_SERVICE_CLIENTS WHERE USER_ID IN(SELECT USER_ID FROM CF_AUTH_USERS WHERE MARKETPLACE_ID=?)",id);jdbc.update("DELETE FROM CF_AUTH_USERS WHERE MARKETPLACE_ID=? AND USER_ROLE='MARKETPLACE'",id);jdbc.update("DELETE FROM CF_MARKETPLACE_REFERENCES WHERE MARKETPLACE_ID=?",id);jdbc.update("DELETE FROM CF_ORGANIZATIONS WHERE ORGANIZATION_ID=?",id);return Map.of("deleted",true);
 }
 private static String hash(List<String> fields){try{var hash=MessageDigest.getInstance("SHA-256");for(String field:fields){byte[] bytes=field.getBytes(StandardCharsets.UTF_8);hash.update(java.nio.ByteBuffer.allocate(4).putInt(bytes.length).array());hash.update(bytes);}return HexFormat.of().formatHex(hash.digest());}catch(Exception ex){throw new IllegalStateException(ex);}}
}
